def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n <= 2:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_a = me[-1]
    last_b = op[-1]

    opp_c = 0
    for x in op:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    w = min(10, n)
    rec_d10 = 0
    for i in range(n - w, n):
        if op[i] == 'D':
            rec_d10 += 1

    w = min(20, n)
    rec_d20 = 0
    for i in range(n - w, n):
        if op[i] == 'D':
            rec_d20 += 1

    w = min(5, n)
    rec_d5 = 0
    for i in range(n - w, n):
        if op[i] == 'D':
            rec_d5 += 1
    rec_c5 = w - rec_d5

    tail_d = 0
    idx = n - 1
    while idx >= 0 and op[idx] == 'D':
        tail_d += 1
        idx -= 1

    pre_c = 0
    while idx >= 0 and op[idx] == 'C':
        pre_c += 1
        idx -= 1

    tail_c = 0
    idx = n - 1
    while idx >= 0 and op[idx] == 'C':
        tail_c += 1
        idx -= 1

    m = min(16, n - 1)
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for i in range(n - 1 - m, n - 1):
        if me[i] == 'C':
            if op[i + 1] == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if op[i + 1] == 'C':
                dc += 1
            else:
                dd += 1

    periodic = False
    if n >= 20:
        win = min(25, n)
        has_c = False
        has_d = False
        for x in op[n - win:]:
            if x == 'C':
                has_c = True
            else:
                has_d = True

        if has_c and has_d:
            cstart = max(1, n - win + 1)
            copy = 0
            tot = 0
            for i in range(cstart, n):
                tot += 1
                if op[i] == me[i - 1]:
                    copy += 1
            cr = float(copy) / float(tot) if tot > 0 else 0.5

            if cr < 0.82:
                best = 0.0
                maxp = min(10, n // 3)
                for p in range(2, maxp + 1):
                    st = max(p, n - win)
                    total2 = n - st
                    if total2 >= 2 * p:
                        match = 0
                        for i in range(st, n):
                            if op[i] == op[i - p]:
                                match += 1
                        rate = float(match) / float(total2)
                        if rate > best:
                            best = rate
                if best >= 0.82:
                    periodic = True

    very_coop = opp_c * 100 >= n * 65
    nonret = False
    if very_coop:
        if dc >= 2 and dc > dd and rec_d10 <= 7:
            nonret = True
        if dc >= 1 and dd == 0 and rec_d20 <= 6 and tail_c >= 2:
            nonret = True

    if last_b == 'C':
        if periodic or nonret:
            return 'D'
        return 'C'

    if periodic:
        return 'D'

    if rec_d10 >= 7 or opp_d * 10 >= n * 65:
        return 'D'

    if pre_c >= 8 and tail_d <= 3 and very_coop:
        return 'C'

    if tail_d <= 1 and opp_c * 100 >= n * 65 and cd <= 1 and rec_d10 <= 1:
        return 'C'

    if last_a == 'C' and dd >= 1 and opp_c * 100 >= n * 65 and rec_d10 <= 7:
        return 'C'

    if last_a == 'D' and tail_d <= 4 and rec_c5 >= 1 and opp_c * 100 >= n * 55 and rng.random() < 0.40:
        return 'C'

    if last_a == 'D' and pre_c >= 10 and tail_d <= 10 and rec_c5 >= 1 and opp_c * 100 >= n * 55 and rng.random() < 0.18:
        return 'C'

    return 'D'
